import unittest
from candidate import search


class TestSearch(unittest.TestCase):
    def test_normal_case_returns_two(self):
        self.assertEqual(search([4, 1, 2, 2, 3, 1]), 2)

    def test_normal_case_returns_three(self):
        self.assertEqual(search([1, 2, 2, 3, 3, 3, 4, 4, 4]), 3)

    def test_normal_case_no_valid_integer_returns_neg_one(self):
        self.assertEqual(search([5, 5, 4, 4, 4]), -1)

    def test_single_one_returns_one(self):
        self.assertEqual(search([1]), 1)

    def test_single_two_returns_neg_one(self):
        self.assertEqual(search([2]), -1)

    def test_all_ones_returns_one(self):
        self.assertEqual(search([1, 1, 1]), 1)

    def test_three_ones_returns_three(self):
        self.assertEqual(search([3, 3, 3]), 3)

    def test_three_twos_returns_two(self):
        self.assertEqual(search([2, 2, 2]), 2)

    def test_two_ones_returns_one(self):
        self.assertEqual(search([1, 1]), 1)

    def test_greatest_valid_integer_is_selected(self):
        self.assertEqual(search([1, 1, 1, 2, 2]), 2)

    def test_multiple_valid_returns_greatest(self):
        self.assertEqual(search([1, 1, 2, 2, 3, 3, 3]), 3)

    def test_all_four_returns_four(self):
        self.assertEqual(search([4, 4, 4, 4]), 4)

    def test_three_fours_returns_neg_one(self):
        self.assertEqual(search([4, 4, 4]), -1)

    def test_ten_tens_returns_ten(self):
        self.assertEqual(search([10] * 10), 10)

    def test_nine_tens_returns_neg_one(self):
        self.assertEqual(search([10] * 9), -1)

    def test_large_number_insufficient_frequency(self):
        self.assertEqual(search([100, 100]), -1)

    def test_mixed_valid_and_invalid_returns_valid(self):
        self.assertEqual(search([1, 1, 5, 5, 5, 5]), 1)

    def test_mixed_all_valid_returns_greatest(self):
        self.assertEqual(search([1, 1, 5, 5, 5, 5, 5]), 5)

    def test_only_invalid_large_numbers(self):
        self.assertEqual(search([7, 7, 7, 8, 8]), -1)

    def test_one_and_many_twos(self):
        self.assertEqual(search([1, 2, 2, 2, 2]), 2)

    def test_duplicate_pairs(self):
        self.assertEqual(search([2, 2, 1]), 2)

    def test_frequency_exactly_equal_to_value(self):
        self.assertEqual(search([5, 5, 5, 5, 5]), 5)

    def test_frequency_one_less_than_value(self):
        self.assertEqual(search([5, 5, 5, 5]), -1)

    def test_empty_list_raises_value_error(self):
        with self.assertRaises(ValueError):
            search([])

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            search(None)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            search("hello")

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            search(5)

    def test_list_with_floats_raises_or_behaves(self):
        with self.assertRaises((TypeError, IndexError)):
            search([1.5, 2.5])

    def test_list_with_none_elements(self):
        with self.assertRaises(TypeError):
            search([1, None, 2])

    def test_single_element_repeated_six_times(self):
        self.assertEqual(search([6, 6, 6, 6, 6, 6]), 6)

    def test_single_element_repeated_seven_times(self):
        self.assertEqual(search([7, 7, 7, 7, 7, 7, 7]), 7)

    def test_one_and_three_threes(self):
        self.assertEqual(search([1, 3, 3, 3]), 3)

    def test_order_independence(self):
        self.assertEqual(search([3, 1, 2, 2, 3, 3, 1]), 3)

    def test_order_independence_reversed(self):
        self.assertEqual(search([1, 3, 3, 3, 2, 2, 1]), 3)

    def test_no_zero_or_negative_in_valid_input(self):
        self.assertEqual(search([1, 1, 1, 1, 1, 1]), 1)


if __name__ == '__main__':
    unittest.main()
